            private readonly IComparer<IReadOnlyGlobalMessageBinder> _inner;
            public GlobalMessageBinderIdTieBreakComparer(IComparer<IReadOnlyGlobalMessageBinder> inner) { _inner = inner; }
            public int Compare(IReadOnlyGlobalMessageBinder? a, IReadOnlyGlobalMessageBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                var c = _inner.Compare(a, b);
                if (c != 0) return c;
                return Comparer<GlobalMessageId>.Default.Compare(a.Id, b.Id);
            }
        }
    }
}
